const MORPH_FRAMES = 121;   // yaku x14: scaleY ramp length (measured 5->6 gap)

// stadiumGeometry(events, idx) -> what the stadium looks like at frame idx:
//   null                      neutral at rest (caller draws STAGES[3] as-is)
//   { unknown: true }         unrecognised transformation id (modded stage) —
//                             caller falls back to ground marks, no platforms
//   { main, platforms, extra} full drawing: closed main polygon (form ground
//                             profile spliced onto the base underside),
//                             platform segments, extra = wheel arm segments.
// `events` is the bundle's stage_state.stadium list [[idx, event, id], ...]
// (sorted, short). Stateless per idx — seeking anywhere renders the same
// picture. Morph phases (events 4/5) squash/grow the form's y by the game's
// own scaleY ramp, so terrain melts down and rises exactly like in-game.
export function stadiumGeometry(events, idx) {
  if (!events || !events.length || events[0][0] > idx) return null;
  let active = 5;       // completed form so far; matches start at neutral
  let last = null;      // latest event at or before idx
  let waterT5 = null;   // when the water form last started growing (wheel phase)
  for (const e of events) {
    if (e[0] > idx) break;
    last = e;
    if (e[1] === 5 && e[2] === 9) waterT5 = e[0];
    if (e[1] === 6 || e[1] === 0) {
      active = e[2];
      // carry event = a completion with no ev-5 in this window: the grow ramp
      // ended MORPH_FRAMES+1 before ev 0 (measured 5->6->0 gaps 121+1)
      if (e[2] === 9 && waterT5 === null) waterT5 = e[0] - MORPH_FRAMES - 1;
    }
  }
  const [te, ev, id] = last;
  let form = active, s = 1, ty = 0;
  if (ev === 4) {                     // old terrain shrinking (then held flat)
    form = active;
    s = Math.max(0.05, 1 - 0.95 * ((idx - te) / MORPH_FRAMES));
  } else if (ev === 5) {              // new terrain growing, rising from y-10
    const dt = idx - te;
    form = id;
    s = Math.min(1, 0.05 + 0.95 * (dt / MORPH_FRAMES));
    ty = dt < MORPH_FRAMES / 2 ? -10 * (1 - dt / (MORPH_FRAMES / 2)) : 0;
  }
  const F = STADIUM_FORMS[form];
  if (!F) return { unknown: true };
  if (form === 5 && s === 1) return null;
  const Y = (y) => y * s + ty;
  const main = [[-87.75, 0]];
  for (const [x, y] of F.profile) main.push([x, Y(y)]);
  main.push([87.75, 0]);
  for (const p of STADIUM_UNDERSIDE) main.push(p);   // base never morphs
  const platforms = F.platforms.map((pf) => [[pf[0][0], Y(pf[0][1])], [pf[1][0], Y(pf[1][1])]]);
  const extra = [];
  if (F.wheel) {
    // -0.5 deg/frame from the grow-start frame, base angle 0 (jobj rz = 0);
    // scaleY squashes the whole sub-ground about y=0, hub included
    const th = -(idx - (waterT5 !== null ? waterT5 : te)) * Math.PI / 360;
    const [hx, hy] = F.wheel.hub, R = F.wheel.r;
    for (const a of [th, th + Math.PI / 2]) {
      const cx = Math.cos(a) * R, cy = Math.sin(a) * R;
      extra.push([hx - cx, Y(hy - cy), hx + cx, Y(hy + cy)]);
    }
  }
  main.push([...main[0]]);
  // The fill keeps the base and the form apart, as the simulator does: one
  // outline spliced from both crosses itself while the form sinks or rises
  // below the floor, and a self-crossing outline cancels out of the fill.
  let fills = null;
  if (F.profile.length) {
    const prof = F.profile.map(([x, y]) => [x, Y(y)]);
    const low = Math.min(-5, ...prof.map((p) => p[1] - 1));
    fills = [[[-87.75, 0], [-70, 0], [-70, -5], [70, -5], [70, 0], [87.75, 0], ...STADIUM_UNDERSIDE],
      [...prof, [prof[prof.length - 1][0], low], [prof[0][0], low]]];
  }
  return { main, platforms, extra, fills };
}

